SELECT data_id, data_name, data_type, book_id, book_name, org_id, org_name, period, amount, currency, status, create_by, create_time, update_by, update_time FROM finance_data
AND data_name LIKE '%' || #{params.dataName} || '%'
AND data_type = #{params.dataType}
AND book_id = #{params.bookId}
AND org_id = #{params.orgId}
AND period = #{params.period}
AND status = #{params.status}
ORDER BY create_time DESC

SELECT data_id, data_name, data_type, book_id, book_name, org_id, org_name, period, amount, currency, status, create_time FROM finance_data
AND data_type = #{params.dataType}
AND book_id = #{params.bookId}
AND org_id = #{params.orgId}
AND period = #{params.period}
ORDER BY create_time DESC

SELECT SUBJECT_ID as "subjectId", SUBJECT_CODE as "subjectCode", SUBJECT_NAME as "subjectName", SUBJECT_TYPE as "subjectType", SUBJECT_LEVEL as "subjectLevel", BALANCE_DIRECTION as "balanceDirection", IS_ENABLED as "isEnabled", IS_LEAF as "isLeaf", PARENT_SUBJECT_ID as "parentSubjectId", BOOK_ID as "bookId", TENANT_ID as "tenantId", CREATE_TIME as "createTime", UPDATE_TIME as "updateTime" FROM TBL_ACCOUNT_SUBJECT
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND SUBJECT_CODE LIKE '%' || #{subjectCode} || '%'
AND SUBJECT_NAME LIKE '%' || #{subjectName} || '%'
AND SUBJECT_TYPE = #{subjectType}
AND SUBJECT_LEVEL = #{subjectLevel}
AND IS_ENABLED = #{isEnabled}
ORDER BY SUBJECT_CODE ASC

SELECT COUNT(*)
FROM TBL_ACCOUNT_SUBJECT


        AND BOOK_ID = #{bookId}


        AND TENANT_ID = #{tenantId}


        AND SUBJECT_CODE LIKE '%' || #{subjectCode} || '%'


        AND SUBJECT_NAME LIKE '%' || #{subjectName} || '%'


        AND SUBJECT_TYPE = #{subjectType}


        AND SUBJECT_LEVEL = #{subjectLevel}


        AND IS_ENABLED = #{isEnabled}
